    public void showLogin() {
        ((CardLayout) getLayout()).show(this, CARD_LOGIN);
        loginPanel.focusUsername();
    }

    public void showRegister() {
        ((CardLayout) getLayout()).show(this, CARD_REGISTER);
        registerPanel.focusUsername();
    }

